import{_ as t,c as n,j as e,a as l,o as _}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第六十七章 如何才能不再生死轮回","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/67第六十七章 如何才能不再生死轮回.md","filePath":"meditation/巴利文大藏经/67第六十七章 如何才能不再生死轮回.md"}'),r={name:"meditation/巴利文大藏经/67第六十七章 如何才能不再生死轮回.md"};function o(s,a,i,d,p,c){return _(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第六十七章-如何才能不再生死轮回",tabindex:"-1"},[l("第六十七章 如何才能不再生死轮回 "),e("a",{class:"header-anchor",href:"#第六十七章-如何才能不再生死轮回","aria-label":'Permalink to "第六十七章 如何才能不再生死轮回"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部12相应38经/思经(因缘相应/因缘篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，内心思考、计划做任何的事情，内心有烦恼产生或是有烦恼产生的趋势，「业识」就会有存在和继续累积发展的根据地。这个「业识」是什么呢？就是一切身体行为，口说言语，内心念想造作后，未来将会承受的各种结果和果报的积累，只是积累还没有发生、出现承受果报的具体结果。当积累到一定的量后，就会去承受之前行为、言语、念想所导致的各种结果和果报。比如做善事就会积累下未来受善报的结果，做恶事就会积累下未来承受恶报的结果，当这些做善事的行为、言语、念想积累到一定量的时候，就会发生、出现承受善果报的结果。当这些做恶事的行为、言语、念想积累到一定量的时候，就会发生、出现承受恶果报的结果。积累行为、言语、念想造作后所导致未来果报和结果的容纳器，就叫「业识」。当然这个容纳器是如来的比喻，因为各种行为、言语、念想的造作要积累到一定的量才会导致未来的果报和结果，与容纳器的功用很像。",-1),e("p",null,"当「业识」有根据地的时候，这个「业识」就有依靠的地方，就有立足点。当「业识」在根据地中持续的积累增长，那么就会导致未来世的存在，导致未来会继续的投生、再生。当未来真的再生，真的再次投生到世间的时候，那么因为已经出生在世间了，就会产生愁闷、忧虑、悲伤、痛苦、绝望、衰老、死亡、再次的出生在世间，就会在喜怒哀乐等等的烦恼和痛苦中循环往复、无有穷尽的煎熬和沉沦。这个就是世间人和众生烦恼和痛苦聚集、出现的过程。",-1),e("p",null,"弟子们，如果内心不思考、不计划做任何的事情，但是内心还有烦恼产生或是有烦恼产生的趋势，那么「业识」还是会有存在和继续累积发展的根据地。当「业识」有根据地的时候，这个「业识」还是会有依靠的地方，还是会有立足点。当「业识」在根据地中持续的积累增长，那么就会导致未来世的存在，导致未来会继续的投生、再生。当未来真的再生，真的再次投生到世间的时候，那么因为已经出生在世间了，就会产生愁闷、忧虑、悲伤、痛苦、绝望、衰老、死亡、再次的出生在世间，就会在喜怒哀乐等等的烦恼和痛苦中循环往复、无有穷尽的煎熬和沉沦。这个就是世间人和众生烦恼和痛苦聚集、出现的过程。",-1),e("p",null,"弟子们，如果内心不思考、不计划做任何的事情，内心没有烦恼的产生，没有烦恼产生的趋势，那么「业识」就没有存在和继续累积发展的根据地。当「业识」没有根据地的时候，这个「业识」就没有依靠的地方，就没有立足点。那么「业识」就不会持续的积累增长，就不会导致未来世的存在，就不会导致未来会继续的投生、再生。当未来没有再生，没有再次投生到世间的时候，那么因为没有出生在世间，就不会产生愁闷、忧虑、悲伤、痛苦、绝望、衰老、死亡，就不会再次出生在世间，就不会在喜怒哀乐等等的烦恼和痛苦中循环往复、无有穷尽的煎熬和沉沦。出生、愁闷、忧虑、悲伤、痛苦、绝望、衰老、死亡就被灭除殆尽了，这个就是世间人和众生烦恼和痛苦彻底灭除、灭尽的过程。这样去修行就不会再生死轮回了，就从生死轮回的烦恼和痛苦中永远的解脱出来。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(r,[["render",o]]);export{u as __pageData,f as default};
